  VALUES ('cmsgrcj4nfwy2tickreez', 'NY Horticulture Group: NYC Landscape Design', 'ny-horticulture-group-nyc-landscape-desi-b0c76b', 'landscaping', '\+1 646-581-1987', 'grow@nyhort.com', 'http://nyhort.com/', '151 W 19th St, New York, NY 10011', 'US', 'USD', 'New York', 'NY', '10011', 40.7414585, -73.9964641, 25, 'business', true, true, 'free', false, 4.8, 18, 'NY Horticulture Group: NYC Landscape Design — landscaping in New York', '<p>Hardscapes, irrigation, gardens, and seasonal displays by NY Horticulture Group .</p>
