INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrcltbld3tun3z7hti', 'Field Form', 'field-form-81c8c7', 'landscaping', '\+1 212-791-7464', 'hello@fieldform.nyc', 'https://www.fieldform.nyc/', '301 Douglass St, Brooklyn, NY 11217', 'US', 'USD', NULL, 'NY', '11217', 40.6800697, -73.98340999999999, 25, 'business', true, true, 'free', false, 5, 3, 'Field Form — landscaping', '<p>Field Form is a landscape design and build firm based in the Gowanus neighborhood of Brooklyn, New York City. Our small, versatile group of designer-builder-gardeners offers a full range of landscaping and garden services, nearly all of which we are proud to self-perform. We work on both private and</p>', 'Field Form — landscaping | Fieseros', 'Book Field Form for landscaping services in your area. Professional, reliable, and trusted by local customers. Rated 5.0★ (3 reviews).', '["landscaping"]', '{"emailSource":"website_scrape","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:08:32.111Z","seedSource":"google-places"}', 5, 'ChIJDapCkV1bwokR7cfD9fWcDRA', '2026-08-06T00:08:44.418Z', '2026-08-06T00:08:44.418Z')
