INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrcodlz1tyrnk2pr91', 'SCAPE Landscape Architecture', 'scape-landscape-architecture-2b0ab7', 'landscaping', '\+1 212-462-2628', NULL, 'http://scapestudio.com/', 'Ninth Floor, 277 Broadway, New York, NY 10007', 'US', 'USD', 'New York', 'NY', '10007', 40.71444950000001, -74.00645639999999, 25, 'business', true, true, 'free', false, 4.8, 6, 'SCAPE Landscape Architecture — landscaping in New York', '<p>We are a collaborative landscape architecture and urban design practice that shapes beloved places that are socially vibrant and ecologically restorative. Every scale is essential. From 100-mile river corridors to rooftop microplazas, our work combines design excellence and a deep knowledge of ecology to regenerate, connect, and transform the built environment.</p>
<p>We are biased toward action, implementation, and learning by doing. To meet the climate crisis, society must simultaneously shift to a renewable economy and adapt our landscapes for the change to come. SCAPE partners with cities, non-profits, and developers to physically transform our world to meet the moment. We center biodiversity and love for the natural world as a climate solution in all of our work.</p>
<p>We see ourselves as co-designing alongside the plants, animals, and of course, people that we share space with on the planet. Our participatory process is equal parts design strategy and community conversation. We start by researching a site’s social, ecological, physical, and historical context, weaving this information into visual stories that invite people into a design conversation. We convene…</p>', 'SCAPE Landscape Architecture — landscaping in New York | Fieseros', 'Book SCAPE Landscape Architecture for landscaping services in New York. Professional, reliable, and trusted by local customers. Rated 4.8★ (6 reviews).', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:08:35.433Z","seedSource":"google-places"}', 6, 'ChIJJYtQ_CFawokRMOSi8npl5w0', '2026-08-06T00:08:44.418Z', '2026-08-06T00:08:44.418Z')
  ON CONFLICT ("googlePlaceId") DO NOTHING;

INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrclyi5geajl653l3n', 'Town and Gardens, Ltd.', 'town-and-gardens-ltd-42fdb6', 'landscaping', '\+1 212-685-6566', NULL, 'http://www.townandgardens.com/', '50-02 23rd St, Long Island City, NY 11101', 'US', 'USD', NULL, 'NY', '11101', 40.7415579, -73.9476706, 25, 'business', true, true, 'free', false, 4.6, 9, 'Town and Gardens, Ltd. — landscaping', '<p>For over 30 years, we have designed, built, and maintained landscapes across New York City. Our work includes high-end residential gardens, rooftops, terraces, courtyard spaces, and thoughtfully programmed amenity environments that balance aesthetics, comfort, and long-term performance.</p>
<p>Transform your outdoor space with our professional landscape design process. Collaborate with our team to create vibrant and captivating environments that ignite inspiration and bring joy to every moment spent outdoors.</p>
<p>Allow our team of landscape maintenance professionals consisting of horticulturalists, low-voltage accent lighting & irrigation technicians, to keep your garden looking its best, year-round. Consult with your dedicated Account Manager to add interest to your space with annual displays throughout the four seasons.</p>
<p>Share your vision for your outdoor space and let our expert team bring your NYC home to life.</p>', 'Town and Gardens, Ltd. — landscaping | Fieseros', 'Book Town and Gardens, Ltd. for landscaping services in your area. Professional, reliable, and trusted by local customers. Rated 4.6★ (9 reviews).', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:08:32.298Z","seedSource":"google-places"}', 13, 'ChIJn4OOii9ZwokRNERx5Kvm1o8', '2026-08-06T00:08:44.418Z', '2026-08-06T00:08:44.418Z')
