INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrcknzvqc0r8cibjfa', 'New Eco Landscapes', 'new-eco-landscapes-4de080', 'landscaping', '\+1 646-770-3602', NULL, 'https://www.newecolandscapes.com/', '25 Broadway 9th floor, New York, NY 10004', 'US', 'USD', 'New York', 'NY', '10004', 40.7055953, -74.0139712, 25, 'business', true, true, 'free', false, 5, 1, 'New Eco Landscapes — landscaping in New York', '<p>New Eco Landscapes is a Manhattan & Brooklyn based landscape design and construction company offering full-service design, installation and maintenance services. From rooftops and terrace garden designs to modern brownstone backyards with native plant selections, built-in furniture and custom hardscaping, we create outdoor spaces that are uniquely yours.</p>
<p>Explore our portfolio of select landscape design projects completed throughout Manhattan and Brooklyn, featuring modern backyards, terraces and rooftop gardens in NYC, Brooklyn & Long Island. Select a project to view a full gallery & additional project details.</p>
<p>This loft-like brownstone in Brooklyn, New York needed a landscape that could stand up to it’s massive character. Our clients wanted a wide open space for their 2 children and 2 golden labs to play. Seating and grilling areas were requested, along with a need for good drainage.</p>
<p>We build and install our landscape designs locally in NYC, Brooklyn, Queens and beyond. The process starts with an on-site consultation, but If you''re not within our reach, we can still work with you to develop a landscape design to suit your outdoor space, with a full design…</p>', 'New Eco Landscapes — landscaping in New York | Fieseros', 'Book New Eco Landscapes for landscaping services in New York. Professional, reliable, and trusted by local customers. Rated 5.0★ (1 reviews).', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:08:30.623Z","seedSource":"google-places"}', 15, 'ChIJdZGq2elbwokR_uiW0_TE8mQ', '2026-08-06T00:08:44.418Z', '2026-08-06T00:08:44.418Z')
  ON CONFLICT ("googlePlaceId") DO NOTHING;

INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrclrg15klfs5ds2xo', 'Flo''s Gardens - Garden Design and Maintenance', 'flos-gardens-garden-design-and-maintenan-f81ded', 'landscaping', '\+1 347-489-9683', NULL, 'https://flosgardens.com/', '121 Congress St, Brooklyn, NY 11201', 'US', 'USD', NULL, 'NY', '11201', 40.6890906, -73.9978823, 25, 'business', true, true, 'free', false, 4.6, 19, 'Flo''s Gardens - Garden Design and Maintenance — landscaping', '<p>There''s much to see here. So, take your time, look around, and learn all there is to know about us. We hope you enjoy our site and take a moment to drop us a line.</p>
<p>Flos''Gardens was founded in 2004 by two friends who share a love for gardening: Florence Sheers and Cecilia Kuhn. Florence grew-up among the roses of her father''s nursery and afterwards trained as a florist. Cecilia studied architecture and business, then transfered her love of design, to gardens. Both were born in France but draw inspiration from many sources, especially English gardens, in developing customized design solutions for each of their clients.They are united by their passion for creating natural, renewable and beautiful green spaces in an urban environment and have worked their magic on gardens and decks for clients from Park Slope to Brooklyn Heights and Manhattan.</p>
<p>- garden maintenance - garden design and installation, - landscaping - windowboxes, planters and seasonals,</p>
<p>Dorothy in cobble hill said: Florence and Cecilia are real pro''s. They have a wealth of knowledge about plants and garden design that they apply to making my brownstone garden a place I enjoy every day. I''m very…</p>', 'Flo''s Gardens - Garden Design and Maintenance — construction | Fiesero', 'Book Flo''s Gardens - Garden Design and Maintenance for landscaping services in your area. Professional, reliable, and trusted by local customers. Rated 4.', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:08:32.044Z","seedSource":"google-places"}', 3, 'ChIJlYSt30RawokRrYQxpULY2Us', '2026-08-06T00:08:44.418Z', '2026-08-06T00:08:44.418Z')
  ON CONFLICT ("googlePlaceId") DO NOTHING;

