INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrd2zulci0g1wb1ep8', 'Garden Design & Landscapes', 'garden-design-landscapes-fd1b42', 'landscaping', '\+1 323-377-3937', NULL, 'http://www.gardendesignandlandscapes.com/', '3612 Barham Blvd, Los Angeles, CA 90068', 'US', 'USD', 'Los Angeles', 'CA', '90068', 34.136868, -118.3409441, 25, 'business', true, true, 'free', false, 4.8, 22, 'Garden Design & Landscapes — landscaping in Los Angeles', '<p>We provide exceptional landscaping services to a wide range of commercial and residential properties for 10 years. Our experienced landscapers set the standard each day in landscape design, paving, hardscaping. We will whip your yard into shape in no time. Residential & commercial.</p>
<p>Hardscape materials include those used to build the no-changing structure of the landscape. They include natural and manufactured stone; wood; and others.</p>
<p>Softscape materials are the living components of a landscape. They include grass; flowers; trees; shrubs and other plants that make up the outdoor home.</p>
<p>With so many years of experience in the business, our company is your source for the highest quality and landscaping service.</p>
<p>Landscape design is the art of arranging or modifying the features of a landscape for aesthetic or practical purposes.</p>
<p>A successful yard does not simply happen for a Landscape designer, or a Landscape architect, or a Landscape contractor. Design is the starting point, with the analysis and creative ability not only to organize the garden to accept what you want within the boundaries, but also to absorb and embrace what lies beyond.</p>', 'Garden Design & Landscapes — landscaping in Los Angeles | Fieseros', 'Book Garden Design & Landscapes for landscaping services in Los Angeles. Professional, reliable, and trusted by local customers. Rated 4.8★ (22 reviews).', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:08:54.378Z","seedSource":"google-places"}', 11, 'ChIJz9aHyLO_woARY-b0GmrmUdg', '2026-08-06T00:08:57.850Z', '2026-08-06T00:08:57.850Z')
