INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrd7k2bc5fmzeu9nua', 'Picture Build', 'picture-build-df474d', 'landscaping', '\+1 818-514-8764', 'office@picturebuild.com', 'https://www.picturebuild.com/?utm_campaign=gmb', '12410 Foothill Blvd Unit U, Sylmar, CA 91342', 'US', 'USD', 'Los Angeles', 'CA', '91342', 34.2844492, -118.4069117, 25, 'business', true, true, 'free', false, 4.8, 86, 'Picture Build — landscaping in Los Angeles', '<p>We are a one-stop shop, complete design/build landscape firm. We do everything, from designing your project, to completing your permits, to building your dream.</p>
<p>We design to a budget, not just for a “great” design. This means you avoid the disappointment of an incredible plan that’s financially out of reach. You have absolutely nothing to lose and everything to gain by exploring the possibilities with us. Let’s create something beautiful together!</p>
<p>Our talented designer will visit your property, armed with a satellite-based plan of your space. Initial consultation is on us! It’s all about understanding your property’s potential and your aspirations.</p>
<p>We’ll walk the site together, discuss your desires and sketch out ideas in real time. This isn’t just any sketch; it’s an architecturally scaled drawing, ensuring that every proposed improvement translates from paper to your actual landscape.</p>
<p>Once you love the overall design concept, our designer will provide you with a clear, realistic ballpark estimate for the project. You’ll know exactly what to expect, empowering you to make informed decisions.</p>
<p>If our design resonates with you and the budget…</p>', 'Picture Build — landscaping in Los Angeles | Fieseros', 'Book Picture Build for landscaping services in Los Angeles. Professional, reliable, and trusted by local customers. Rated 4.8★ (86 reviews).', '["landscaping"]', '{"emailSource":"website_scrape","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:09:00.290Z","seedSource":"google-places"}', 5, 'ChIJ8Q8lTKeUwoAR6BWN_ukNDwo', '2026-08-06T00:09:10.006Z', '2026-08-06T00:09:10.006Z')
  ON CONFLICT ("googlePlaceId") DO NOTHING;

