INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrdjzbc4327sywli14', 'GreenTree Landscaping', 'greentree-landscaping-2f29fe', 'landscaping', '\+1 323-468-9740', NULL, 'http://greentreela.com/', '849 Highland Ave, Los Angeles, CA 90038', 'US', 'USD', 'Los Angeles', 'CA', '90038', 34.086666699999995, -118.33891919999999, 25, 'business', true, true, 'free', false, 5, 5, 'GreenTree Landscaping — landscaping in Los Angeles', '<p>Our team sees every job as a privilege and a responsibility. Our mission is to lead people into a love affair with their gardens, to help them to collaborate with Nature as an artistic partner.</p>
<p>Wherever we’re asked to begin, in the end we have one purpose: to create beautiful surroundings that nurture and inspire.</p>
<p>The roots of GreenTree’s landscaping operations are personal, starting when our founder Michael Baer was a small boy following behind his father’s tractor on the family’s farm.</p>
<p>At 15, Michael inherited his older brother’s car, invested in a lawn mower and lined up neighbors as his first clients. Eventually he left the family farm, worked his way up to become Captain of a fire engine company, finished a political science degree at UCLA and traveled the world (literally) as a foreign-post journalist. But after living and working in more than 13 countries throughout Africa, Asia, the Middle East, Europe, and South America, Baer returned to Southern California and his childhood home.</p>
<p>Formally opening GreenTree Landscaping in the early 1980s, Baer designed the business around twin aspirations: creating beautiful natural surroundings and building…</p>', 'GreenTree Landscaping — landscaping in Los Angeles | Fieseros', 'Book GreenTree Landscaping for landscaping services in Los Angeles. Professional, reliable, and trusted by local customers. Rated 5.0★ (5 reviews).', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:09:16.391Z","seedSource":"google-places"}', 2, 'ChIJsT6xlCy_woARZmki1fALv0Q', '2026-08-06T00:09:16.392Z', '2026-08-06T00:09:16.392Z')
