INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrdqnt6verupwb42nu', 'Arts Landscaping & Maintenance LLC', 'arts-landscaping-maintenance-llc-f67e5a', 'landscaping', '\+1 773-900-8738', 'info@artsmaintenance.com', 'http://artsmaintenance.com/', '3146 W 59th St, Chicago, IL 60629', 'US', 'USD', 'Chicago', 'IL', '60629', 41.786431199999996, -87.7028016, 25, 'business', true, true, 'free', false, 4.9, 128, 'Arts Landscaping & Maintenance LLC — landscaping in Chicago', '<p>We keep things straightforward, one team, clear communication, and no bouncing between multiple crews. You will always know who is working on your property, and we will always treat it with care.</p>
<p>As a locally owned company based in Chicago, we bring a personal approach to every job. Our team offers complete lawn care, seasonal cleanups, planting, hardscaping, and everything in between. We serve homeowners, property managers, and business owners who want dependable results without the runaround.</p>
<p>Taking care of your lawn goes beyond a simple mow. We offer a full range of lawn care services to keep your grass healthy, green, and growing strong throughout Chicago''s seasons. Our seasonal approach helps prevent damage and supports lush, even growth all year long.</p>
<p>Regular mowing services to maintain a neat, professional look and encourage healthy growth. We adjust mowing height based on the season and grass type to keep it strong and avoid stress.</p>
<p>We break up compacted soil and overseed to promote thicker, stronger turf. This allows better water flow and root development for a more vibrant, resilient lawn.</p>', 'Arts Landscaping & Maintenance LLC — landscaping in Chicago | Fiesero', 'Book Arts Landscaping & Maintenance LLC for landscaping services in Chicago. Professional, reliable, and trusted by local customers. Rated 4.9★ (128 revie', '["landscaping"]', '{"emailSource":"website_scrape","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:09:25.049Z","seedSource":"google-places"}', 12, 'ChIJZ6gyZgB270YR9VuRzK17cAk', '2026-08-06T00:09:29.735Z', '2026-08-06T00:09:29.735Z')
