INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrdqrt70db7yzkxnd9', 'Tommy Pollina Landscape Company', 'tommy-pollina-landscape-company-2059af', 'landscaping', '\+1 847-698-6868', 'info@tommypollina.com', 'https://www.tommypollina.com/', '420 N River Rd, Mt Prospect, IL 60056', 'US', 'USD', 'Mount Prospect', 'IL', '60056', 42.0751268, -87.8940568, 25, 'business', true, true, 'free', false, 4.8, 226, 'Tommy Pollina Landscape Company — landscaping in Mount Prospect', '<p>At Tommy Pollina Landscape Company, we understand that your yard is a complex, living system. It’s not just a lawn, a patio, or a row of plants—it’s a network of interconnected elements. When one component is out of alignment, it can impact the function and health of every other aspect. For 45 years, we’ve specialized in designing and installing outdoor environments that function cohesively. Our approach combines beautiful and functional design for: drainage systems, proper grading, plant material, hardscape elements, lawn maintenance, irrigation, lighting, and more—all engineered to work in harmony.</p>
<p>True landscape performance doesn’t happen by chance. It requires thoughtful integration of every trade and every detail. That’s what sets us apart: nearly half a century of experience ensuring every outdoor system we install works together, and stands the test of time.</p>
<p>After more than 45 years working across the Chicago area , we''ve learned something that most homeowners only learn the hard way:</p>
<p>If a hardscape contractor doesn''t bring up drainage engineering from day one, it''s because they don''t know how to do it.</p>', 'Tommy Pollina Landscape Company — landscaping in Mount Prospect | Fie', 'Book Tommy Pollina Landscape Company for landscaping services in Mount Prospect. Professional, reliable, and trusted by local customers. Rated 4.8★ (226 r', '["landscaping"]', '{"emailSource":"website_scrape","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:09:25.193Z","seedSource":"google-places"}', 10, 'ChIJn_n2oWC0D4gREBmPqG3ZoUc', '2026-08-06T00:09:29.737Z', '2026-08-06T00:09:29.737Z')
  ON CONFLICT ("googlePlaceId") DO NOTHING;

