INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrdv0xi6w1eyhkmrvv', 'Hernandez Lawn care LLC', 'hernandez-lawn-care-llc-660759', 'landscaping', '\+1 312-806-8284', NULL, 'https://hernandezlawncarellc.com/', '17803 Dogwood Ln, Hazel Crest, IL 60429', 'US', 'USD', 'Hazel Crest', 'IL', '60429', 41.5660448, -87.68586429999999, 25, 'business', true, true, 'free', false, 4.7, 12, 'Hernandez Lawn care LLC — landscaping in Hazel Crest', '<p>Chicago’s weather is tough on landscapes. From brutal winters with freezing temperatures and heavy snowfall to scorching summers and unpredictable rainstorms, maintaining a healthy, green lawn is no easy task. Severe winter freeze leads to compaction of the soil, frost heaving and damage to plants, and de-icing salts on roads kills grass and trees. Summer’s heat island effect, caused by the city’s high concrete density, stresses plants and dries out soil faster than normal. Add in Chicago’s strict zoning and landscaping regulations , including parkway removal permits and stormwater runoff compliance, and it’s clear—DIY landscaping isn’t enough. That’s where Hernandez Lawn Care comes in.</p>
<p>We take pride in delivering high-quality, customized landscaping services to Chicago & nearby areas that keep your yard healthy, vibrant, and compliant with city regulations.</p>
<p>Whether you need a simple lawn upgrade or a full landscape transformation, Hernandez Lawn Care is here to help! Our landscapers provide customized expert lawn care and landscaping services tailored to Chicago’s unique climate, zoning regulations, and outdoor space challenges.</p>', 'Hernandez Lawn care LLC — landscaping in Hazel Crest | Fieseros', 'Book Hernandez Lawn care LLC for landscaping services in Hazel Crest. Professional, reliable, and trusted by local customers. Rated 4.7★ (12 reviews).', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:09:30.705Z","seedSource":"google-places"}', 5, 'ChIJ15NDNlIZDogRC4FaudFir24', '2026-08-06T00:09:39.607Z', '2026-08-06T00:09:39.607Z')
  ON CONFLICT ("googlePlaceId") DO NOTHING;

