INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrehpjb0cf33sqz000', 'Four Seasons Lawn & Landscaping LLC', 'four-seasons-lawn-landscaping-llc-fdb4b7', 'landscaping', '\+1 832-916-3000', NULL, 'https://www.fourseasonsdesigns.biz/', '7200 Eldridge Pkwy Ste C, Houston, TX 77083', 'US', 'USD', 'Houston', 'TX', '77083', 29.702902199999997, -95.62529300000001, 25, 'business', true, true, 'free', false, 4.5, 69, 'Four Seasons Lawn & Landscaping LLC — landscaping in Houston', '<p>Four Seasons Lawn & Landscaping provides professional lawn service and landscape maintenance for homeowners, HOA communities, and commercial properties throughout Southwest Houston and surrounding established neighborhoods.</p>
<p>We focus on structured service, dependable scheduling, and long-term property performance — not high-volume mowing routes.</p>
<p>If you''re looking for consistency, clear communication, and a company that treats your property like an asset, not a quick stop, we''re built for that.</p>
<p>Some companies chase volume. Others disappear mid-season. We operate on defined routes within the communities we already serve so we can maintain service quality and consistency week after week.</p>
<p>Maintaining turf in Southwest Houston requires more than cutting grass. Heat stress, heavy rainfall, compacted soil, and aggressive weeds demand proactive lawn maintenance. Our programs are built around long-term turf health and clean property presentation.</p>
<p>HOA-managed communities require organization, reliability, and clear communication.</p>', 'Four Seasons Lawn & Landscaping LLC — landscaping in Houston | Fieser', 'Book Four Seasons Lawn & Landscaping LLC for landscaping services in Houston. Professional, reliable, and trusted by local customers. Rated 4.5★ (69 revie', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:10:00.103Z","seedSource":"google-places"}', 11, 'ChIJOzqlTXLhQIYRujYzZ5lM7hM', '2026-08-06T00:10:06.362Z', '2026-08-06T00:10:06.362Z')
