  VALUES ('cmsgreknaxssq7nzdsjf0', 'LawnStarter - Houston Landscaping', 'lawnstarter-houston-landscaping-17b899', 'landscaping', '\+1 832-981-4636', NULL, 'https://www.lawnstarter.com/houston-tx-landscaping/?utm_source=google&utm_medium=GLocal&utm_campaign=HoustonGLocal', '2400 Hackett Dr, Houston, TX 77008', 'US', 'USD', 'Houston', 'TX', '77008', 29.808032299999994, -95.43421579999999, 25, 'business', true, true, 'free', false, 5, 64, 'LawnStarter - Houston Landscaping — landscaping in Houston', '<p>A new, easy way to get landscaping in Houston. Choose from 50+ services including mowing, cleanups, installations and more.</p>
