INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrexx0eyga4mex8z51', 'Desert Crest, LLC', 'desert-crest-llc-1d084d', 'landscaping', '\+1 623-780-8900', NULL, 'https://www.desertcrestllc.com/', '704 W Happy Valley Rd, Phoenix, AZ 85085', 'US', 'USD', 'Phoenix', 'AZ', '85085', 33.7136472, -112.0834014, 25, 'business', true, true, 'free', false, 5, 32, 'Desert Crest, LLC — landscaping in Phoenix', '<p>Desert Crest Landscape, LLC is a trusted landscape designer in Phoenix, Arizona, specializing in landscape design , xeriscaping, and outdoor living spaces built for the Sonoran Desert. Our expert landscape designers create beautiful, functional, and sustainable landscapes that thrive in the Arizona desert climate.</p>
<p>Our Phoenix landscape design services begin with a detailed consultation at your home, where we discuss your vision, lifestyle, and budget. We then develop a custom master plan that integrates native plants, hardscaping, and water-efficient systems to deliver a landscape that''s both stunning and sustainable.</p>
<p>We use resilient desert plants like Palo Verde trees, Saguaro cacti, Agave, and Lantana—all of which thrive with minimal irrigation. Each xeriscape design emphasizes water conservation and low-maintenance beauty, helping you save on water costs while enhancing curb appeal.</p>
<p>Our Phoenix landscape design team goes beyond planting. We create cohesive layouts for patios, walkways, outdoor kitchens , and entertainment areas, considering the intense Arizona sun and implementing strategic shading for year-round comfort.</p>', 'Desert Crest, LLC — landscaping in Phoenix | Fieseros', 'Book Desert Crest, LLC for landscaping services in Phoenix. Professional, reliable, and trusted by local customers. Rated 5.0★ (32 reviews).', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:10:21.108Z","seedSource":"google-places"}', 5, 'ChIJP1J2dZtvK4cRalx0Ohe-ecA', '2026-08-06T00:10:24.637Z', '2026-08-06T00:10:24.637Z')
