INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrfhoc8m8ua0ae5lyg', 'Urban Jungle', 'urban-jungle-fc1f2a', 'landscaping', '\+1 215-952-0811', 'hello@urbanjunglephilly.com', 'http://urbanjunglephilly.com/', '1526 Passyunk Ave, Philadelphia, PA 19147', 'US', 'USD', 'Philadelphia', 'PA', '19147', 39.9303911, -75.1630773, 25, 'business', true, true, 'free', false, 4.4, 310, 'Urban Jungle — landscaping in Philadelphia', '<p>Urban Jungle''s President, Curt Alexander, grew up on a vineyard in California. Growing up in California fostered his love of horticulture, and attending West Point to obtain a mechanical engineering education honed his engineering design skills. When he moved to Philadelphia, he realized how stark the city is with its'' brick and mortar, concrete, and sidewalks. For his taste, it lacked life and greenery— so he did something about it.</p>
<p>Starting with his own house, he and his wife Tara put in window boxes, hanging baskets, planters, and created a green facade. It wasn’t long before people would come by and ask, “Can you do this for me?” So they would do the same for friends and neighbors— and that’s how it started.</p>
<p>After recognizing the demand for greenery within the city, Alexander opened a retail shop in South Philadelphia in 2009. Urban Jungle has sat on Passyunk Ave for over a decade with the mission of bringing nature to the urban environment. We sell everything you need for your houseplants, from the soil to the plant itself. As Tara says, plants make people happy— and we want to bring that happiness to our community in Philadelphia.</p>', 'Urban Jungle — landscaping in Philadelphia | Fieseros', 'Book Urban Jungle for landscaping services in Philadelphia. Professional, reliable, and trusted by local customers. Rated 4.4★ (310 reviews).', '["landscaping"]', '{"emailSource":"website_scrape","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:10:46.716Z","seedSource":"google-places"}', 14, 'ChIJkYhoHxvGxokRslXjvlAiSuk', '2026-08-06T00:10:49.134Z', '2026-08-06T00:10:49.134Z')
  ON CONFLICT ("googlePlaceId") DO NOTHING;

