INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrgf4cnhhbqf191j87', 'Kreative Landscaping Design & Build', 'kreative-landscaping-design-build-fd55a8', 'landscaping', '\+1 858-333-7051', 'info@kreativelandscaping.com', 'http://www.kreativelandscaping.com/', '2535 Fenton Pkwy, San Diego, CA 92108', 'US', 'USD', 'San Diego', 'CA', '92108', 32.7831471, -117.1305701, 25, 'business', true, true, 'free', false, 5, 7, 'Kreative Landscaping Design & Build — landscaping in San Diego', '<p>Vision Review - In our first meeting, your designer will listen to your vision, your wants, budgets, and requirements for your space.</p>
<p>Design - Next we begin working on customizing a design specific to your requirements, building out 3D renderings/images.</p>
<p>Client Review - Your designer will share a complete, detailed plan for your space, providing 3D renderings/images for your review and work on further customizing your design based on your feedback.</p>
<p>Build - We will provide you with a detailed cost estimate to have our partnered team of professionals build out your completed design space and bring it to life!</p>
<p>We help clients transform their yards into extraordinary resort-style living. Using 3D imaging software, we''re able to take concepts, dreams, rough hand-sketched drawings (even blueprints) and convert them into amazing 3D images so our clients can see what the potential of their outdoor space and how it can be transform.</p>', 'Kreative Landscaping Design & Build — landscaping in San Diego | Fies', 'Book Kreative Landscaping Design & Build for landscaping services in San Diego. Professional, reliable, and trusted by local customers. Rated 5.0★ (7 revi', '["landscaping"]', '{"emailSource":"website_scrape","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:11:30.060Z","seedSource":"google-places"}', 8, 'ChIJPcJBzGOr3oAR52Sj_SwI1Cw', '2026-08-06T00:11:36.388Z', '2026-08-06T00:11:36.388Z')
