INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrh0f5bbv8rq4r21py', 'Austin Creative Landscaping LLC', 'austin-creative-landscaping-llc-9a1ee5', 'landscaping', '\+1 512-552-5677', NULL, 'http://www.austincreativelandscaping.com/', '11506 Easy St, Austin, TX 78748', 'US', 'USD', 'Austin', 'TX', '78748', 30.152436899999994, -97.83239979999999, 25, 'business', true, true, 'free', false, 4.9, 68, 'Austin Creative Landscaping LLC — landscaping in Austin', '<p>Austin, Texas landscaping done right. We design and build custom outdoor living spaces from native gardens and hardscape to artificial turf and landscape lighting. Born in Austin. Built for Texas. Let us create, so you can enjoy!</p>
<p>For over 16 years, Austin Creative Landscaping has been crafting outdoor spaces that feel like home. We are not just installers. We are designers, gardeners, masons, and craftspeople who care deeply about the land we work on.</p>
<p>Every project starts the same way: a quiet walk on your property, a conversation about how you live, and a sketch on paper. From there we draw, we build, and we plant, always with a deep respect for native Texas landscapes.</p>
<p>From the first sketch to the last plant in the ground, we are your single team for every part of your outdoor build. Residential and commercial, across South Austin and the Hill Country.</p>
<p>Imagine. Design. Build. It all starts with a great design built around your land, your life, and your budget.</p>
<p>Patios, pergolas, walkways, retaining walls, and outdoor kitchens built from honest materials that age beautifully in the Texas climate.</p>', 'Austin Creative Landscaping LLC — landscaping in Austin | Fieseros', 'Book Austin Creative Landscaping LLC for landscaping services in Austin. Professional, reliable, and trusted by local customers. Rated 4.9★ (68 reviews).', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:11:57.665Z","seedSource":"google-places"}', 5, 'ChIJ3Yaho6tNW4YRkmQIPb5VrDE', '2026-08-06T00:12:07.863Z', '2026-08-06T00:12:07.863Z')
  ON CONFLICT ("googlePlaceId") DO NOTHING;

