INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrhgk8ixm3mppzxl20', 'Water and Earth Landscape Design', 'water-and-earth-landscape-design-e4d7bc', 'landscaping', '\+1 408-560-6362', NULL, 'http://www.waterandearthld.com/', '1702-L Meridian Ave #347, San Jose, CA 95125', 'US', 'USD', 'San Jose', 'CA', '95125', 37.292839, -121.912497, 25, 'business', true, true, 'free', false, 4.8, 23, 'Water and Earth Landscape Design — landscaping in San Jose', '<p>To get more information about working together, please fill out our Project Questionnaire. Once we receive it we will quickly review and reach out to schedule some time for a Discovery Call which is the first step in our onboarding process.</p>
<p>Not sure where to start? Already know what direction to go but need some advice? Meet with principal designer Matt for a 60 or 75 minute paid virtual consult and ask anything, get solutions to your problems, unbiased feedback and prepare to save a significant amount of time and money.</p>
<p>Learn more about Water & Earth Landscape Design and all the services we offer our Southern California clients.</p>
<p>Get advice directly from the W&E Landscape Design blog. Tips, tricks and advice on your next landscape design project.</p>
<p>Stay up to date on the latest trends, styles and design choices in Northern California.</p>', 'Water and Earth Landscape Design — landscaping in San Jose | Fieseros', 'Book Water and Earth Landscape Design for landscaping services in San Jose. Professional, reliable, and trusted by local customers. Rated 4.8★ (23 reviews', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:12:18.584Z","seedSource":"google-places"}', 10, 'ChIJE3QZGJg0joARabpNAfJE614', '2026-08-06T00:12:27.122Z', '2026-08-06T00:12:27.122Z')
