INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrhg1ywn4907r4y5vg', 'Westack Landscaping', 'westack-landscaping-9f4075', 'landscaping', '\+1 408-581-5555', NULL, 'https://westacklandscaping.com/', '221 San Jose Ave, San Jose, CA 95125', 'US', 'USD', 'San Jose', 'CA', '95125', 37.309311799999996, -121.87530249999999, 25, 'business', true, true, 'free', false, 5, 28, 'Westack Landscaping — landscaping in San Jose', '<p>Your outdoor space deserves more than just grass—it deserves thoughtful design, clean finishes, and materials built to last. At Westack Landscaping , we create low-maintenance, high-impact spaces with custom artificial turf , paver patios , and full backyard transformations .</p>
<p>We’re not a franchise. We’re your local Bay Area landscaping team , known for high-quality work, honest pricing, and results that last. When you work with us, you’re choosing peace of mind and beautiful outcomes.</p>
<p>At Westack Landscaping , we offer a full range of outdoor services tailored to California’s climate, water restrictions, and architectural styles. Whether you need a simple upgrade or a full landscape transformation, we bring the tools, the talent, and the vision.</p>
<p>If you’re tired of brown spots, high water bills, and the hassle of lawn maintenance, artificial turf is the perfect solution. We install premium synthetic grass that looks natural, feels soft underfoot, and lasts for years. Ideal for front yards, backyards, playgrounds, and pet-friendly homes.</p>
