  VALUES ('cmsgrhvf2k6yf3c21vdkt', 'PURE LANDSCAPING of SAN JOSE', 'pure-landscaping-of-san-jose-e86062', 'landscaping', '\+1 707-625-5738', NULL, 'https://purelandscapingca.com/', '265 Meridian Ave, San Jose, CA 95126', 'US', 'USD', 'San Jose', 'CA', '95126', 37.3241455, -121.91423909999999, 25, 'business', true, true, 'free', false, 5, 3, 'PURE LANDSCAPING of SAN JOSE — landscaping in San Jose', '<p>Full custom landscape designs built around your vision, lifestyle, and property.</p>
