INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrjpaae90jaho90k58', 'Big Visions Landscaping', 'big-visions-landscaping-a52887', 'landscaping', '\+1 704-457-9769', NULL, 'https://bigvisionslandscaping.com/', '4510 Old Pineville Rd, Charlotte, NC 28217', 'US', 'USD', 'Charlotte', 'NC', '28217', 35.181553199999996, -80.8797518, 25, 'business', true, true, 'free', false, 4.3, 58, 'Big Visions Landscaping — landscaping in Charlotte', '<p>Big Visions Landscaping works with homeowners in Charlotte, North Carolina, and nearby communities on landscape design , hardscape installation, and ongoing maintenance. Lauren walks each property in person before any design work begins. Call our team or fill out the contact form to schedule your site visit.</p>
<p>Charlotte lots often have grade changes, underused backyard space, or no defined area for outdoor seating. Hardscapes address those problems with permanent structures that hold up through weather and add space you can actually use.</p>
<p>Sloped terrain in Charlotte loses soil during heavy rain and limits what can be planted or built on the hillside. A retaining wall holds that grade in place and creates flat, usable ground above it. We build walls in natural stone, concrete block, or brick to fit the scale of the property and the style of the home.</p>
<p>A paver patio gives you a stable, level surface that handles foot traffic, furniture, and a grill without cracking or shifting. Pavers manage Charlotte''s temperature swings better than poured concrete and hold their appearance for years. We design the layout based on how you want to use the space and how it…</p>', 'Big Visions Landscaping — landscaping in Charlotte | Fieseros', 'Book Big Visions Landscaping for landscaping services in Charlotte. Professional, reliable, and trusted by local customers. Rated 4.3★ (58 reviews).', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:14:03.202Z","seedSource":"google-places"}', 9, 'ChIJ612h_xyfVogR9S3Ei439koo', '2026-08-06T00:14:05.347Z', '2026-08-06T00:14:05.347Z')
  ON CONFLICT ("googlePlaceId") DO NOTHING;

