INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrkbgx7kn3cbcph36e', 'Arterra Landscape Architects', 'arterra-landscape-architects-408619', 'landscaping', '\+1 415-861-3100', NULL, 'http://arterrasf.com/', '88 Missouri St, San Francisco, CA 94107', 'US', 'USD', 'San Francisco', 'CA', '94107', 37.765473, -122.397116, 25, 'business', true, true, 'free', false, 5, 5, 'Arterra Landscape Architects — landscaping in San Francisco', '<p>Arterra is a full-service landscape architecture firm specializing in contemporary, sustainable design. We collaborate with our clients and their design team, providing imaginative solutions and clear communication.</p>
<p>The Arterra Team is a diverse and slightly quirky group of creative and nerdy individuals. We are dedicated to the art and the craft of our profession. We consider it an honor and a privilege to do the work we do — and we do it well.</p>
<p>We share ideas and inspiration in our beautiful, open studio space, where design ideas come to life. We are dedicated to doing sustainable work, and living sustainable lives.</p>
<p>Our greatest achievement is creating a meaningful and sustainable landscape legacy. We welcome your queries and commissions.</p>', 'Arterra Landscape Architects — landscaping in San Francisco | Fiesero', 'Book Arterra Landscape Architects for landscaping services in San Francisco. Professional, reliable, and trusted by local customers. Rated 5.0★ (5 reviews', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:14:31.953Z","seedSource":"google-places"}', 2, 'ChIJ33sIFcx_j4ARwS12xpOg7Zw', '2026-08-06T00:14:40.758Z', '2026-08-06T00:14:40.758Z')
