INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrkc5ok63wibnqk1kf', 'Growsgreen Landscape Design', 'growsgreen-landscape-design-b24eca', 'landscaping', '\+1 415-336-9829', NULL, 'http://www.growsgreen.com/', '1082 Pennsylvania Ave, San Francisco, CA 94107', 'US', 'USD', 'San Francisco', 'CA', '94107', 37.753361, -122.393046, 25, 'business', true, true, 'free', false, 5, 1, 'Growsgreen Landscape Design — landscaping in San Francisco', '<p>Beth Mullins specializes in building and designing. She designs modern residential gardens and interiors for clients all over the United States. With a Ph.D. from the University of Pennsylvania and a Masters in Landscape Architecture from UC Berkeley, both science and horticulture influence her sculptural landscapes, plant palettes and airy interiors.</p>
<p>Beth’s designs have been recognized in many books and landscape publications including Sunset Magazine, Pacific Horticulture, and Garden Design. Growsgreen has won awards from the CLCA, and the San Francisco Flower and Garden show. Her favorite color is texture. View more of Beth''s design work on Remodelista , Houzz , Pinterest , and Instagram and in these publications . View Beth’s interior work at here for interior design from an exterior perspective.</p>
<p>Beth’s studio practice involved working spatially in clay and mixed media at bethelliottstudio.com and viewable on Instagram mixed in with her interior and landscape design feed. Art is an integral way for her to process connections and spaces with her hands as an extension of her design and building concepts to create unique sculptural and functional vessels. The…</p>', 'Growsgreen Landscape Design — landscaping in San Francisco | Fieseros', 'Book Growsgreen Landscape Design for landscaping services in San Francisco. Professional, reliable, and trusted by local customers. Rated 5.0★ (1 reviews)', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:14:32.844Z","seedSource":"google-places"}', 10, 'ChIJi4OasrF_j4ARmIOFlxcpKzE', '2026-08-06T00:14:40.758Z', '2026-08-06T00:14:40.758Z')
  ON CONFLICT ("googlePlaceId") DO NOTHING;

