INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrkabq5cu8smfn34lw', 'RareField Design/ Build', 'rarefield-design-build-8679cb', 'landscaping', '\+1 415-824-1882 ext. 102', NULL, 'https://www.rarefieldsf.com/', '766 Valencia St, San Francisco, CA 94110', 'US', 'USD', 'San Francisco', 'CA', '94110', 37.760655799999995, -122.4218219, 25, 'business', true, true, 'free', false, 5, 12, 'RareField Design/ Build — landscaping in San Francisco', '<p>We design and build landscapes and interiors that feel honest and human. Places to breathe, stretch out, sit still, put your feet up, drink your coffee, or ditch the to-do list for a minute. Outdoor rooms, patios, gardens, interior remodels, and full design-build projects built with care, practicality, and the kind of craft that holds up over time.</p>
<p>We keep things collaborative and straightforward. Clear costs, real timelines, smart materials, and no hidden drama. From day one, we look at feasibility, construction realities, and long-term upkeep so what we build actually works. No fluff, no ego, just spaces that make life feel a little better, day after day.</p>
<p>Our design approach is thoughtful and layered, shaped by the character of the site and the rhythms of your daily life. We take time to understand how you move through a space, what you value, and what will make the environment feel like home. Form and function are considered together, allowing beauty and practicality to reinforce each other rather than compete. The result is a design that doesn’t demand attention but creates a quiet sense of belonging,something that feels settled, honest, and entirely your…</p>', 'RareField Design/ Build — landscaping in San Francisco | Fieseros', 'Book RareField Design/ Build for landscaping services in San Francisco. Professional, reliable, and trusted by local customers. Rated 5.0★ (12 reviews).', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:14:30.470Z","seedSource":"google-places"}', 11, 'ChIJcbycIj1-j4ARkhLWJAAurcM', '2026-08-06T00:14:40.758Z', '2026-08-06T00:14:40.758Z')
  ON CONFLICT ("googlePlaceId") DO NOTHING;

