INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrkc2yfgrngbfu8zdd', 'The Foxy Garden', 'the-foxy-garden-c73ec2', 'landscaping', '\+1 415-794-8192', 'audrey@thefoxygarden.com', 'https://www.thefoxygarden.com/', '2944 23rd St, San Francisco, CA 94110', 'US', 'USD', 'San Francisco', 'CA', '94110', 37.7544617, -122.41101489999998, 25, 'business', true, true, 'free', false, 5, 1, 'The Foxy Garden — landscaping in San Francisco', '<p>Audrey Newell is a landscape designer and ceramic artist living in San Francisco and practicing throughout the Bay Area. During her first career as a scientific model maker, she crafted habitat dioramas for natural history museums and visitor centers worldwide. After about a decade, she realized that sculpting, molding, and painting fantastically real looking models of the natural world was fantastically unnatural. Audrey decided it was time to step back and observe the natural world in a different way altogether. She now creates living habitats for real local inhabitants.</p>
<p>Audrey holds a BFA from SF State University with a dual major in Sculpture and Conceptual Design, and an AA in Landscape Architecture from Merritt College’s Landscape Horticulture department. Her background in arts fabrication and her equally extensive hands-on experience in garden maintenance have made Audrey the thoughtful and detailed oriented designer she is today.</p>
<p>The Foxy Garden delivers residential designs that are personal, creative, and responsive to clients'' needs, enriching urban spaces and making our outdoor environments count. Her work today is rooted in regenerative design…</p>', 'The Foxy Garden — landscaping in San Francisco | Fieseros', 'Book The Foxy Garden for landscaping services in San Francisco. Professional, reliable, and trusted by local customers. Rated 5.0★ (1 reviews).', '["landscaping"]', '{"emailSource":"website_scrape","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:14:32.746Z","seedSource":"google-places"}', 5, 'ChIJAStZuG1_j4ARLfQZGTpsgOs', '2026-08-06T00:14:40.758Z', '2026-08-06T00:14:40.758Z')
  ON CONFLICT ("googlePlaceId") DO NOTHING;

INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrkbpaundjzrx6pnto', 'Urban FarmGirls Garden Design', 'urban-farmgirls-garden-design-94b098', 'landscaping', '\+1 415-244-6254', NULL, 'http://www.shopurbanfarmgirlsco.com/', '1615 Cortland Ave, San Francisco, CA 94110', 'US', 'USD', 'San Francisco', 'CA', '94110', 37.7398997, -122.4086124, 25, 'business', true, true, 'free', false, 4.5, 11, 'Urban FarmGirls Garden Design — landscaping in San Francisco', '<p>Use left/right arrows to navigate the slideshow or swipe left/right if using a mobile device</p>
<p>Urban Farmgirls(UFG) rustic and modern Pozzola Pottery is now produced and offered by Rock & Rose Landscapes Design Studio and Workshop.</p>
<p>-- A creative extension of Rock & Rose Landscapes providing a collaborative design, meeting, and planning space for its creative teams, builders, clients, and project principals, as well a workshop and production space for its award winning landscape installations, garden enhancements, and now custom rustic pottery, garden accessories, and more.</p>
<p>Urban Farmgirls'' bold and versatile aesthetic, carries on with the continued combining of modern lines with rustic materials to achieve a characterful, stylish, and livable feel that lends itself well to almost any decorative style, garden environment, or outdoor space.</p>
<p>This design impetus has led to the development of our collection of artisan garden products that capture that design aesthetic; none more so than our small batch and custom order Pozzola planters, all designed and made by hand in our San Francisco design studio and workshop.</p>', 'Urban FarmGirls Garden Design — landscaping in San Francisco | Fieser', 'Book Urban FarmGirls Garden Design for landscaping services in San Francisco. Professional, reliable, and trusted by local customers. Rated 4.5★ (11 revie', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:14:32.254Z","seedSource":"google-places"}', 7, 'ChIJe5EL3Rl_j4ARGixCzqBDTKU', '2026-08-06T00:14:40.758Z', '2026-08-06T00:14:40.758Z')
  ON CONFLICT ("googlePlaceId") DO NOTHING;

