INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrkdiq40l6q8f48z7d', 'Frank & Grossman Landscaping Inc.', 'frank-grossman-landscaping-inc-c03c47', 'landscaping', '\+1 415-822-1900', NULL, 'http://www.frankandgrossman.com/', '1400 Egbert Ave, San Francisco, CA 94124', 'US', 'USD', 'San Francisco', 'CA', '94124', 37.7229919, -122.39266440000002, 25, 'business', true, true, 'free', false, 3.8, 11, 'Frank & Grossman Landscaping Inc. — landscaping in San Francisco', '<p>Frank and Grossman Landscape Contractors, Inc. began right here in the San Francisco Bay Area in 1981. Our humble beginnings were spent building residential and estate landscapes, setting the stage for our passion in the landscape and commercial cleaning industries. Since its inception, our capabilities and expertise have expanded to full-service landscape construction, landscape maintenance, and commercial cleaning services. We have partnerships across the entire San Francisco Bay Area from the South in Carmel, to the East in Brentwood, and North to Sonoma.</p>
<p>Our 250+ craftsmen and women provide our customers with a proactive approach to beautifying and servicing their properties. Our “consider it done” mentality and rigorous dedication to quality and craftsmanship, have won our company over 100 state and local awards.</p>
<p>Our craftsmen and women at Frank + Grossman are dedicated to our partnerships and exceeding all expectations. Specializing in residential and estate maintenance and construction, and commercial landscape and commercial cleaning services, we are your premier partner for all things custom.</p>
<p>Frank and Grossman Landscape Contractors, Inc. provides…</p>', 'Frank & Grossman Landscaping Inc. — landscaping in San Francisco | Fi', 'Book Frank & Grossman Landscaping Inc. for landscaping services in San Francisco. Professional, reliable, and trusted by local customers. Rated 3.8★ (11 r', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:14:34.610Z","seedSource":"google-places"}', 10, 'ChIJKTmigSJ_j4ARlA8jJ3FJyF8', '2026-08-06T00:14:40.758Z', '2026-08-06T00:14:40.758Z')
