INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrkbcmyb2q1lg230bw', 'Mountain Top Construction', 'mountain-top-construction-a32af4', 'landscaping', '\+1 800-988-3778', 'info@mtmountaintop.com', 'https://mtmountaintop.com/', '1407 Gough St Ste 12, San Francisco, CA 94109', 'US', 'USD', 'San Francisco', 'CA', '94109', 37.7865794, -122.4252907, 25, 'business', true, true, 'free', false, 5, 15, 'Mountain Top Construction — landscaping in San Francisco', '<p>Welcome to MT Mountain Top Construction, where excellence meets elevation. With a steadfast commitment to quality craftsmanship and unparalleled dedication to our clients, we stand as a pinnacle in the construction industry. We specialize in commercial and residential construction projects, including new construction, renovations, and additions. Our team has extensive experience and knowledge in the industry, allowing us to provide our clients with top-notch services.</p>
<p>Mountain Top specializes in transforming interior spaces into beautiful, functional, and inviting environments. We collaborate closely with each client to bring their vision to life, ensuring every detail aligns with their expectations. With the help of advanced AI tools, we offer immersive 3D visualizations, allowing you to experience your space before it''s even built.</p>
<p>Additionally, our exclusive virtual showroom features top-tier, trusted brands, giving you access to the best the market has to offer. Our dedicated team is committed to delivering exceptional results, ensuring your project is completed on time and within budget, while staying true to your vision.</p>', 'Mountain Top Construction — landscaping in San Francisco | Fieseros', 'Book Mountain Top Construction for landscaping services in San Francisco. Professional, reliable, and trusted by local customers. Rated 5.0★ (15 reviews).', '["landscaping"]', '{"emailSource":"website_scrape","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:14:31.798Z","seedSource":"google-places"}', 9, 'ChIJYUxZ6PiBhYARj5f2OojA5ZY', '2026-08-06T00:14:40.759Z', '2026-08-06T00:14:40.759Z')
