INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrkbcrrhn5wmrc5qb1', 'Andrea Cochran Landscape Architecture', 'andrea-cochran-landscape-architecture-02aecd', 'landscaping', '\+1 415-503-0060', NULL, 'http://acochran.com/', '2475 3rd St #304, San Francisco, CA 94107', 'US', 'USD', 'San Francisco', 'CA', '94107', 37.7582792, -122.38814599999999, 25, 'business', true, true, 'free', false, 5, 1, 'Andrea Cochran Landscape Architecture — landscaping in San Francisco', '<p>Andrea Cochran Landscape Architecture sculpts space to create timeless, immersive environments for public, commercial, and residential clients.</p>
<p>Andrea Cochran and Alex Strader to Speak at the ASLA 2026 Conference on Landscape Architecture</p>
<p>Andrea Cochran Landscape Architecture is pleased to announce that founder Andrea Cochran and director Alex Strader will be speaking at the 2026 Conference on Landscape Architecture hosted by the American Society of Landscape Architects, taking place September 16–18, 2026.</p>
<p>Andrea will present How It Started…How It’s Going: Stories , while Alex will speak in the sessions Struggles in Practice and Jack of All Trades or Master of One? Landscape Practice Today .</p>
<p>Their participation reflects ACLA’s continued engagement with conversations shaping the future of landscape architecture and professional practice.</p>
<p>The feature highlights a Marin County residence designed by architect Lee F. Mindel, with landscape architecture by Andrea Cochran Landscape Architecture. The story explores how the project thoughtfully integrates art, architecture, and the surrounding landscape to create a cohesive and immersive experience.</p>', 'Andrea Cochran Landscape Architecture — landscaping in San Francisco ', 'Book Andrea Cochran Landscape Architecture for landscaping services in San Francisco. Professional, reliable, and trusted by local customers. Rated 5.0★ (', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:14:31.803Z","seedSource":"google-places"}', 7, 'ChIJw_bkubl_j4ARA_U7_bhQXsY', '2026-08-06T00:14:40.759Z', '2026-08-06T00:14:40.759Z')
  ON CONFLICT ("googlePlaceId") DO NOTHING;

