INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrkqzse555w1r0ni6p', 'Green Garden Landscaping', 'green-garden-landscaping-88c77a', 'landscaping', '\+1 206-930-2699', NULL, 'http://seattlegreengarden.com/', '14309 Midvale Ave N, Seattle, WA 98133', 'US', 'USD', 'Seattle', 'WA', '98133', 47.7326756, -122.34415629999998, 25, 'business', true, true, 'free', false, 5, 66, 'Green Garden Landscaping — landscaping in Seattle', '<p>Expert, full-service landscaping for Seattle-area homes—design, build, and year-round care.</p>
<p>Caring for your plants is how we care for you. Let’s meet in your garden and partner together.</p>
<p>We’re a full-service landscaping company serving Seattle-area homes, HOAs, and commercial properties with a personal, high-touch approach. From landscape design and hardscape construction to irrigation management and year-round maintenance, we keep outdoor spaces healthy, polished, and resilient in the Pacific Northwest climate.</p>
<p>We believe great landscaping comes from clear communication, skilled crews, and consistent standards—whether we’re building your patio or mowing your lawn.</p>
<p>Every landscape is different, so we start by understanding your property, your priorities, and how you want to use your outdoor space. Whether you need ongoing maintenance, a new irrigation system, or a complete landscape transformation, you get one responsive team that communicates clearly, collaborates when decisions matter, and follows through.</p>
<p>We focus on protecting your investment and keeping your landscape looking its best year-round. From lawn care and pruning to seasonal…</p>', 'Green Garden Landscaping — landscaping in Seattle | Fieseros', 'Book Green Garden Landscaping for landscaping services in Seattle. Professional, reliable, and trusted by local customers. Rated 5.0★ (66 reviews).', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:14:52.072Z","seedSource":"google-places"}', 4, 'ChIJz8fohBbsSikR3ZFoXM9oNaw', '2026-08-06T00:14:56.007Z', '2026-08-06T00:14:56.007Z')
  ON CONFLICT ("googlePlaceId") DO NOTHING;

