INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrkwbdgufpkk8tw440', 'Pacific Landscaping, Inc.', 'pacific-landscaping-inc-8cdd03', 'landscaping', '\+1 206-366-0913', NULL, 'http://pacificlandscapinginc.com/', '8828 206th St SE Bldg A, Snohomish, WA 98296', 'US', 'USD', 'Snohomish', 'WA', '98296', 47.8103614, -122.11279899999998, 25, 'business', true, true, 'free', false, 4.6, 70, 'Pacific Landscaping, Inc. — landscaping in Snohomish', '<p>I am SO impressed with the work your crew did on Friday to clean up my landscaping. I now have all these beautiful walkways and vistas that I didn''t realize were there. Please convey my thanks to your people for a job VERY well done!</p>
<p>Absolutely beautiful, the guys did an impressive job: very efficient, professional and thoughtful. All around classy guys. Thank you for being the perfect choice for our "makeover".</p>
<p>The work is exactly what we had hoped for, we are very satisfied and will be in touch in the spring for the backyard. I only had a minute to talk to the guys, but they were very friendly, professional and left everything cleaned up nicely.</p>
<p>Pacific Landscaping worked wonders in my yard. Unable to grow grass because the shade from large Maple trees, Larry recommended plantings and tress to make a garden area. He has a great sense of design and knowledge of plants. Larry talked through everything they were going to do and checked to make sure things were going as planned. The workers are polite, enthusiastic, efficient and thorough. They also placed a brick walk from the front of the house to a back entrance and installed drainage to take rainwater…</p>', 'Pacific Landscaping, Inc. — landscaping in Snohomish | Fieseros', 'Book Pacific Landscaping, Inc. for landscaping services in Snohomish. Professional, reliable, and trusted by local customers. Rated 4.6★ (70 reviews).', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:14:58.969Z","seedSource":"google-places"}', 9, 'ChIJZY7O8a8RkFQR_-tIwbJALpw', '2026-08-06T00:15:03.179Z', '2026-08-06T00:15:03.179Z')
