INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrkuospybq7zykxwyb', 'Monetti Landscape Design and Construction, LLC', 'monetti-landscape-design-and-constructio-e475d2', 'landscaping', '\+1 206-348-2733', NULL, 'http://monettilandscape.com/', '4904 Erskine Way SW, Seattle, WA 98116', 'US', 'USD', 'Seattle', 'WA', '98116', 47.558377799999995, -122.38773659999998, 25, 'business', true, true, 'free', false, 4.8, 18, 'Monetti Landscape Design and Construction, LLC — landscaping in Seattle', '<p>For over 25 years, Monetti Landscape has designed and built custom outdoor spaces for West Seattle homes, from patios and stonework to decks, fences, fire pits, water features, and plant-forward landscapes built for the Pacific Northwest.</p>
<p>Monetti Landscape Design and Construction creates custom outdoor environments that feel beautiful, functional, and built to last. From thoughtful landscape design to expert construction, we help West Seattle homeowners transform challenging yards, sloped lots, small spaces, and aging outdoor areas into places that are easier to use and more enjoyable to live in.</p>
<p>Our work includes stonework , masonry , decks , fences , fire pits , water features , metal fabrication , plantings , and complete landscape design build projects. Every detail is planned with your home, terrain, lifestyle, and long term maintenance in mind.</p>
<p>Custom patios, pathways, retaining walls, and masonry designed for West Seattle terrain and weather.</p>
<p>From cedar fencing to custom decks and structures, built to add long term value and outdoor usability.</p>
<p>Integrated fire and water features designed for year-round outdoor living in Seattle’s climate.</p>', 'Monetti Landscape Design and Construction, LLC — landscaping in Seatt', 'Book Monetti Landscape Design and Construction, LLC for landscaping services in Seattle. Professional, reliable, and trusted by local customers. Rated 4.8', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:14:56.860Z","seedSource":"google-places"}', 9, 'ChIJxxEHhvtAkFQR8yNolv5MyPA', '2026-08-06T00:15:03.180Z', '2026-08-06T00:15:03.180Z')
