INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrle1bq55s0fgvopqi', 'Switchback Colorado Landscape & Sprinkler', 'switchback-colorado-landscape-sprinkler-7af469', 'landscaping', NULL, 'keaton@switchbackcolorado.com', 'https://www.switchbackcolorado.com/', '9658 Havana St Unit C12, Commerce City, CO 80022', 'US', 'USD', 'Commerce City', 'CO', '80022', 39.8714972, -104.86614069999999, 25, 'business', true, true, 'free', false, 5, 132, 'Switchback Colorado Landscape & Sprinkler — landscaping in Commerce City', '<p>Switchback Colorado''s award-winning designs take the art of sustainable environmental care and transforms it into exceptional garden and outdoor living spaces. From landscape design, to lighting, fencing, and irrigation designs, Switchback can meet all your outdoor living needs.</p>
<p>Switchback Colorado''s dedicated maintenance experts perform comprehensive landscape maintenance and preventative care services throughout the year. Our services include mow, trim, blow, edge, spring/fall cleanups, aerating, de-tatching, fertilizing and weed control, tree pruning, fence repair and winterization.</p>
<p>As a proper design & installation firm, we hire the finest craftsmen and present the best materials to create lush gardens and landscapes. We construct and install sprinkler and irrigation systems, pavers, flagstone and retaining walls, fencing and outdoor lighting systems. We do this all while utilizing the best sustainability and conservation practices in the industry.</p>
