INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrltprxypcxtcsp3eo', 'Offshoots Productive Landscapes', 'offshoots-productive-landscapes-c51376', 'landscaping', '\+1 617-500-6530', NULL, 'http://www.offshootsinc.com/', '547 Rutherford Ave, Boston, MA 02129', 'US', 'USD', 'Boston', 'MA', '02129', 42.3826044, -71.0723036, 25, 'business', true, true, 'free', false, 4.9, 30, 'Offshoots Productive Landscapes — landscaping in Boston', '<p>A meticulously renovated historic hobbyist farm in Sudbury, Massachusetts, with a Patrick Ahern-designed addition, reclaimed pool patio, hand-built structures, including a sunken garden with a soapstone fountain, stone-foundation greenhouse, and pine barn on approximately 6 acres.</p>
<p>A bright, lush roof deck garden with drought-tolerant plants and borrowed views of Boston’s Skyline</p>
<p>This vibrant, evolving outdoor landscape utilizes permaculture principles as inspiration for the programming and plant selection.</p>
<p>A low-maintenance perennial garden and poplar allée turn this former vacant lot into a sculptural urban landscape that also helps cleanse the site below.</p>
<p>The primary goal: to create more habitat for pollinators. Our community can make a difference through big and small actions. If we act together, we can respond to local and global pollinator population decline. Check it out here!</p>
<p>Offshoots is a hybrid practice offering landscape architecture, planning, and horticultural installation services. Explore the map below to view a selection of our work across Greater Boston.</p>', 'Offshoots Productive Landscapes — landscaping in Boston | Fieseros', 'Book Offshoots Productive Landscapes for landscaping services in Boston. Professional, reliable, and trusted by local customers. Rated 4.9★ (30 reviews).', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:15:42.255Z","seedSource":"google-places"}', 13, 'ChIJX9gBEuhw44kRu0BbwQbbloY', '2026-08-06T00:15:48.863Z', '2026-08-06T00:15:48.863Z')
