INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrnoiucuon2xp0a62l', 'Brody Pennell Heating & Air Conditioning', 'brody-pennell-heating-air-conditioning-795982', 'landscaping', '\+1 310-896-4911', NULL, 'http://brodypennell.com/', '8599 Venice Blvd., Los Angeles, CA 90034', 'US', 'USD', 'Los Angeles', 'CA', '90034', 34.0344336, -118.380145, 25, 'business', true, true, 'free', false, 4.9, 4909, 'Brody Pennell Heating & Air Conditioning — landscaping in Los Angeles', '<p>Though we are one of the longest-running HVAC companies in the Los Angeles area, we pride ourselves on offering the most up-to-date and efficient heating and cooling systems. While HVAC technologies continue to evolve, we evolve along with them, continually training and mastering the latest in emerging HVAC products and machinery.</p>
<p>Opening our doors in 1945, Brody Pennell has been the Greater Los Angeles area’s most trusted and experienced HVAC team for decades. We have been a proud dealer of Carrier heating and cooling systems and accessories for over 50 years. To this day, we remain the only Carrier Dealer in the West Los Angeles area and the only Carrier Presidents Award Recipient for 2021 in all of LA and Orange Counties.</p>
<p>With 80 years of experience in residential and commercial heating and cooling, we have the expertise and the know-how to bring unique solutions to every HVAC need or concern.</p>
<p>We’re here for you 24/7! To get started with your HVAC service, repair, or replacement, contact Brody Pennell at (310) 810-2721 or contact us online.</p>
<p>By clicking “Send Message”, I am providing express written consent to receive autodialed and pre-recorded…</p>', 'Brody Pennell Heating & Air Conditioning — landscaping in Los Angeles', 'Book Brody Pennell Heating & Air Conditioning for landscaping services in Los Angeles. Professional, reliable, and trusted by local customers. Rated 4.9★ ', '["landscaping"]', '{"emailSource":"none","emailVerified":false,"descriptionSource":"website_scrape","seededAt":"2026-08-06T00:17:08.838Z","seedSource":"google-places"}', 1, 'ChIJZ87Dn365woARcqfL59YnyJo', '2026-08-06T00:17:11.340Z', '2026-08-06T00:17:11.340Z')
