INSERT INTO "Tenant" ("id", "name", "slug", "industry", "phone", "email", "website", "address", "country", "currency", "city", "state", "postalCode", "latitude", "longitude", "serviceRadiusKm", "plan", "marketplaceOptIn", "publicProfileEnabled", "listingTier", "claimed", "rating", "reviewCount", "tagline", "description", "seoTitle", "seoDescription", "businessCategoriesJson", "settingsJson", "employeesCount", "googlePlaceId", "createdAt", "updatedAt")
  VALUES ('cmsgrpz1wxkfjk24s7l9i', 'Way Cool Plumbing & Air', 'way-cool-plumbing-air-ca3605', 'landscaping', '\+1 480-462-3843', NULL, 'http://www.callwaycool.com/', '2328 E Van Buren St Ste 121, Phoenix, AZ 85006', 'US', 'USD', 'Phoenix', 'AZ', '85006', 33.451733499999996, -112.03145049999999, 25, 'business', true, true, 'free', false, 4.8, 829, 'Way Cool Plumbing & Air — landscaping in Phoenix', '<p>Phoenix summers are no joke. AC repair, replacement, and tune-ups — same-day when capacity allows. Built for 115° days.</p>
<p>Phoenix HVAC, plumbing, and home performance — done the Way Cool way since 1982.</p>
<p>Tell us about your home in six quick steps. We''ll match you to the right American Standard, Ruud, Goodman, or Daikin system, with your current APS or SRP rebates factored in.</p>
